// NODO: Calcular Fechas del Mes - Adaptado para movimientos_ivan
// Se ejecuta el día 1 de cada mes para analizar el mes anterior

const now = new Date();
const year = now.getFullYear();
const currentMonth = now.getMonth(); // 0-11

// Calcular mes anterior
const previousMonth = currentMonth === 0 ? 11 : currentMonth - 1;
const previousYear = currentMonth === 0 ? year - 1 : year;

// Primer y último día del mes anterior
const firstDay = new Date(previousYear, previousMonth, 1);
const firstDayStr = firstDay.toISOString().split('T')[0]; // YYYY-MM-DD

const lastDay = new Date(previousYear, previousMonth + 1, 0);
const lastDayStr = lastDay.toISOString().split('T')[0]; // YYYY-MM-DD

// Nombres en español
const monthNames = [
  'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
  'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
];

// Para comparación: mes anterior al anterior
const twoMonthsAgoMonth = previousMonth === 0 ? 11 : previousMonth - 1;
const twoMonthsAgoYear = previousMonth === 0 ? previousYear - 1 : previousYear;
const twoMonthsAgoFirst = new Date(twoMonthsAgoYear, twoMonthsAgoMonth, 1).toISOString().split('T')[0];
const twoMonthsAgoLast = new Date(twoMonthsAgoYear, twoMonthsAgoMonth + 1, 0).toISOString().split('T')[0];

// Cantidad de días del mes analizado
const daysInMonth = lastDay.getDate();

return [{
  json: {
    // Fechas del mes a analizar (mes anterior)
    firstDay: firstDayStr,
    lastDay: lastDayStr,
    monthName: monthNames[previousMonth],
    monthNumber: previousMonth + 1,
    year: previousYear,
    daysInMonth: daysInMonth,
    dateRange: `${firstDayStr} al ${lastDayStr}`,

    // Para comparaciones
    twoMonthsAgoFirst: twoMonthsAgoFirst,
    twoMonthsAgoLast: twoMonthsAgoLast,
    twoMonthsAgoName: monthNames[twoMonthsAgoMonth],

    // Metadata
    executionTime: new Date().toISOString(),
    executionDay: now.getDate(),
    note: `Analizando ${monthNames[previousMonth]} ${previousYear} (ejecutado el día ${now.getDate()} de ${monthNames[currentMonth]})`
  }
}];

// Obtener datos del input (adaptado para n8n)
const inputData = $input.all();
let datos;

// Detectar si es un array o un objeto
if (Array.isArray(inputData) && inputData.length > 0) {
  datos = inputData[0].json;
} else if (inputData.json) {
  datos = inputData.json;
} else {
  datos = inputData;
}

// Si los datos vienen en un array, tomar el primer elemento
if (Array.isArray(datos) && datos.length > 0) {
  datos = datos[0];
}

// Validar que tenemos los datos necesarios
if (!datos || !datos.periodo || !datos.resumen) {
  return [{
    json: {
      error: "Datos incompletos. Se requiere estructura con periodo y resumen",
      received: datos
    }
  }];
}

// Funciones auxiliares para generar gráficos
function getPieColor(index) {
  const colors = [
    '#667eea', '#764ba2', '#f093fb', '#4ade80', '#fbbf24', 
    '#f87171', '#60a5fa', '#a78bfa', '#34d399', '#fb7185'
  ];
  return colors[index % colors.length];
}

function generatePieChartSVG(chartData) {
  if (!chartData || !chartData.labels || !chartData.values) {
    return '<p>No hay datos para mostrar el gráfico</p>';
  }

  const { labels, values } = chartData;
  const total = values.reduce((sum, val) => sum + parseFloat(val || 0), 0);

  if (total === 0) return '<p>No hay datos para mostrar</p>';

  let currentAngle = 0;
  const radius = 80;
  const innerRadius = 40;
  const centerX = 120;
  const centerY = 120;

  const paths = values.map((value, index) => {
    const numValue = parseFloat(value || 0);
    if (numValue === 0) return '';

    const angle = (numValue / total) * 360;

    const startAngle = currentAngle;
    const endAngle = currentAngle + angle;
    currentAngle = endAngle;

    const startAngleRad = (startAngle - 90) * Math.PI / 180;
    const endAngleRad = (endAngle - 90) * Math.PI / 180;

    const x1 = centerX + radius * Math.cos(startAngleRad);
    const y1 = centerY + radius * Math.sin(startAngleRad);
    const x2 = centerX + radius * Math.cos(endAngleRad);
    const y2 = centerY + radius * Math.sin(endAngleRad);

    const x3 = centerX + innerRadius * Math.cos(startAngleRad);
    const y3 = centerY + innerRadius * Math.sin(startAngleRad);
    const x4 = centerX + innerRadius * Math.cos(endAngleRad);
    const y4 = centerY + innerRadius * Math.sin(endAngleRad);

    const largeArc = angle > 180 ? 1 : 0;

    return `<path d="M ${x1} ${y1} A ${radius} ${radius} 0 ${largeArc} 1 ${x2} ${y2} L ${x4} ${y4} A ${innerRadius} ${innerRadius} 0 ${largeArc} 0 ${x3} ${y3} Z" 
            fill="${getPieColor(index)}" stroke="white" stroke-width="2"/>`;
  }).filter(path => path !== '').join('');

  return `
    <svg class="pie-chart" viewBox="0 0 240 240" xmlns="http://www.w3.org/2000/svg">
      ${paths}
      <text x="120" y="115" text-anchor="middle" font-size="12" font-weight="bold" fill="#2c3e50">TOTAL</text>
      <text x="120" y="130" text-anchor="middle" font-size="14" font-weight="bold" fill="#667eea">€${total.toLocaleString('es-ES', {maximumFractionDigits: 0})}</text>
    </svg>
  `;
}

