                    ${parseFloat(datos.resumen.porcentajeAhorro || 0) < 20 ? 
                        '<li>Intenta aumentar tu tasa de ahorro reduciendo gastos en las categorías más altas</li>' : 
                        '<li>Mantén tu excelente tasa de ahorro actual</li>'
                    }
                    ${datos.categorias && datos.categorias.length > 0 && parseFloat(datos.categorias[0].porcentajeDelTotal || 0) > 30 ? 
                        '<li>La categoría "' + datos.categorias[0].nombre + '" representa más del 30% de tus gastos. Considera revisar estos gastos.</li>' : 
                        ''
                    }
                    <li>Promedio diario de gastos: €${parseFloat(datos.resumen.promedioGastoDiario || 0).toLocaleString('es-ES', {maximumFractionDigits: 2})} - úsalo como referencia para tu presupuesto diario</li>
                    ${(datos.resumen.totalMovimientos || 0) < 20 ? 
                        '<li>Registra todos tus movimientos para obtener un análisis más preciso</li>' : 
                        '<li>Excelente registro de movimientos, esto permite un análisis detallado</li>'
                    }
                    ${datos.iva && parseFloat(datos.iva.aLiquidar || 0) > 0 ? 
                        '<li>Recuerda liquidar el IVA trimestral: €' + parseFloat(datos.iva.aLiquidar).toLocaleString('es-ES', {maximumFractionDigits: 2}) + '</li>' : 
                        ''
                    }
                </ul>
            </div>
        </div>

        <!-- Footer -->
        <div class="footer">
            <p>Informe generado automáticamente el ${new Date().toLocaleDateString('es-ES')}</p>
            <p style="margin-top: 8px;">Sistema de Reportes Financieros - n8n Automation</p>
        </div>
    </div>
</body>
</html>
`;

// Retornar el resultado
return [{
  json: {
    htmlContent: htmlContent,
    periodo: datos.periodo,
    resumen: datos.resumen,
    metadata: {
      generatedAt: new Date().toISOString(),
      inputType: Array.isArray(inputData) ? 'array' : 'object',
      hasPlotlyData: !!(datos.plotlyData && datos.plotlyData.categoriasChart),
      totalCategorias: datos.categorias ? datos.categorias.length : 0,
      totalGastos: datos.topGastos ? datos.topGastos.length : 0,
      totalIngresos: datos.topIngresos ? datos.topIngresos.length : 0
    }
  }
}];

// PROCESADOR DE DATOS REALES - Code Node
// Procesa exactamente los datos que vienen del Aggregate

const inputData = $input.first().json;
const movimientos = inputData.data || [];

console.log(`Iniciando procesamiento de ${movimientos.length} movimientos reales`);

// Detectar período automáticamente desde los datos
let fechaMin = null;
let fechaMax = null;

movimientos.forEach(mov => {
  const fecha = mov.fecha;
  if (!fechaMin || fecha < fechaMin) fechaMin = fecha;
  if (!fechaMax || fecha > fechaMax) fechaMax = fecha;
});

// Extraer mes y año del período real
const fechaInicio = new Date(fechaMin);
const mesNombres = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
                   'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];
const mesNombre = mesNombres[fechaInicio.getMonth()];
const año = fechaInicio.getFullYear();
const diasDelMes = new Date(año, fechaInicio.getMonth() + 1, 0).getDate();

console.log(`Período detectado: ${mesNombre} ${año} (${movimientos.length} movimientos)`);

// Inicializar contadores
let totalIngresos = 0;
let totalGastos = 0;
let ivaRepercutido = 0;
let ivaSoportado = 0;
let ivaDeducible = 0;

const categorias = new Map();
const tiposPago = new Map();
const gastosPorDia = new Map();

// Arrays para rankings
const todosLosGastos = [];
const todosLosIngresos = [];

// PROCESAR CADA MOVIMIENTO REAL
movimientos.forEach((mov, index) => {
  console.log(`Procesando ${index + 1}/${movimientos.length}: ${mov.detalle}`);

  const ingreso = parseFloat(mov.ingreso) || 0;
  const gasto = parseFloat(mov.gasto_numeric) || 0;
  const ivaImporte = parseFloat(mov.iva_importe) || 0;
  const baseImponible = parseFloat(mov.base_imponible) || 0;

  // Acumular totales
  totalIngresos += ingreso;
  totalGastos += gasto;

  // Procesar IVA
  if (mov.iva_tipo === 'repercutido') {
    ivaRepercutido += ivaImporte;
  } else if (mov.iva_tipo === 'soportado') {
    ivaSoportado += ivaImporte;
    if (mov.deducible === 'True') {
      ivaDeducible += ivaImporte;
    }
  }

  // Agrupar por categoría
  if (mov.categoria) {
    if (!categorias.has(mov.categoria)) {
      categorias.set(mov.categoria, {
        nombre: mov.categoria,
        gastos: 0,
        ingresos: 0,
        movimientos: 0,
        baseImponible: 0
      });
    }
    const cat = categorias.get(mov.categoria);
    cat.gastos += gasto;
    cat.ingresos += ingreso;
    cat.movimientos += 1;
    cat.baseImponible += baseImponible;
  }

  // Agrupar por tipo de pago
  if (mov.tipo_pago) {
    if (!tiposPago.has(mov.tipo_pago)) {
      tiposPago.set(mov.tipo_pago, {
        tipo: mov.tipo_pago,
        totalGastos: 0,
        totalIngresos: 0,
        cantidad: 0
      });
    }
    const tipo = tiposPago.get(mov.tipo_pago);
    tipo.totalGastos += gasto;
    tipo.totalIngresos += ingreso;
    tipo.cantidad += 1;
  }

  // Agregar a rankings
  if (gasto > 0) {
    todosLosGastos.push({
      fecha: mov.fecha,
      detalle: mov.detalle || 'Sin detalle',
      categoria: mov.categoria || 'Sin categoría',
      subcategoria: mov.subcategoria || '-',
      gasto_numeric: gasto
    });
  }

  if (ingreso > 0) {
    todosLosIngresos.push({
      fecha: mov.fecha,
      detalle: mov.detalle || 'Sin detalle',
      categoria: mov.categoria || 'Sin categoría',
      subcategoria: mov.subcategoria || '-',
      ingreso: ingreso
    });
  }
});

// Calcular métricas derivadas
const balance = totalIngresos - totalGastos;
const porcentajeAhorro = totalIngresos > 0 ? (balance / totalIngresos * 100) : 0;
const ivaALiquidar = ivaRepercutido - ivaDeducible;

// Preparar rankings
const topGastos = todosLosGastos
  .sort((a, b) => b.gasto_numeric - a.gasto_numeric)
  .slice(0, 10);

const topIngresos = todosLosIngresos
  .sort((a, b) => b.ingreso - a.ingreso)
  .slice(0, 5);

// Convertir categorías a array ordenado
const categoriasArray = Array.from(categorias.values())
  .map(cat => ({
    ...cat,
    gastos: cat.gastos.toFixed(2),
    ingresos: cat.ingresos.toFixed(2),
    baseImponible: cat.baseImponible.toFixed(2),
    porcentajeDelTotal: totalGastos > 0 ? ((cat.gastos / totalGastos) * 100).toFixed(2) : '0.00'
  }))
  .sort((a, b) => parseFloat(b.gastos) - parseFloat(a.gastos));

// Convertir tipos de pago a array
const tiposPagoArray = Array.from(tiposPago.values())
  .map(tipo => ({
    tipo: tipo.tipo,
    totalGastos: tipo.totalGastos.toFixed(2),
    totalIngresos: tipo.totalIngresos.toFixed(2),
    cantidad: tipo.cantidad
  }))
  .sort((a, b) => parseFloat(b.totalGastos) - parseFloat(a.totalGastos));

// Generar insights basados en datos reales
const insights = [];

if (porcentajeAhorro < 10) {
  insights.push({
    tipo: 'alerta',
    mensaje: `Tasa de ahorro crítica (${porcentajeAhorro.toFixed(1)}%)`,
    recomendacion: 'Revisar urgentemente gastos no esenciales'
  });
} else if (porcentajeAhorro >= 20) {
  insights.push({
    tipo: 'positivo',
    mensaje: `Tasa de ahorro saludable (${porcentajeAhorro.toFixed(1)}%)`,
    recomendacion: 'Mantener este buen hábito financiero'
  });
} else {
  insights.push({
    tipo: 'advertencia',
    mensaje: `Tasa de ahorro mejorable (${porcentajeAhorro.toFixed(1)}%)`,
    recomendacion: 'Optimizar gastos para alcanzar el 20%'
  });
}

if (Math.abs(ivaALiquidar) > 10) {
  insights.push({
    tipo: 'info',
    mensaje: `IVA ${ivaALiquidar > 0 ? 'a liquidar' : 'a favor'}: ${Math.abs(ivaALiquidar).toFixed(2)} €`,
    recomendacion: ivaALiquidar > 0 ? 'Preparar liquidación trimestral' : 'Considerar solicitar devolución'
  });
}

console.log(`Procesamiento completado: ${movimientos.length} movimientos de ${mesNombre} ${año}`);

// OUTPUT FINAL - Estructura exacta para el generador HTML
return [{
  json: {
    periodo: {
      monthName: mesNombre,
      year: año,
      firstDay: fechaMin,
      lastDay: fechaMax,
      daysInMonth: diasDelMes,
      dateRange: `${fechaMin} al ${fechaMax}`
    },
    resumen: {
      totalIngresos: totalIngresos.toFixed(2),
      totalGastos: totalGastos.toFixed(2),
      balance: balance.toFixed(2),
      porcentajeAhorro: porcentajeAhorro.toFixed(2),
      totalMovimientos: movimientos.length,
      promedioGastoDiario: (totalGastos / diasDelMes).toFixed(2),
      promedioIngresoDiario: (totalIngresos / diasDelMes).toFixed(2)
    },
    iva: {
      repercutido: ivaRepercutido.toFixed(2),
      soportado: ivaSoportado.toFixed(2),
      soportadoDeducible: ivaDeducible.toFixed(2),
      aLiquidar: ivaALiquidar.toFixed(2),
      porcentajeDeducible: ivaSoportado > 0 ? ((ivaDeducible / ivaSoportado) * 100).toFixed(1) : '0'
    },
    categorias: categoriasArray,
    topGastos: topGastos,
    topIngresos: topIngresos,
    tiposPago: tiposPagoArray,
    insights: insights,
    plotlyData: {
      categoriasChart: {
        labels: categoriasArray.map(c => c.nombre),
        values: categoriasArray.map(c => parseFloat(c.gastos))
      }
    },
    procesamiento: {
      fecha: new Date().toISOString(),
      version: 'data_driven_v1.0',
      registrosProcesados: movimientos.length,
      periodoReal: `${mesNombre} ${año}`,
      fechaInicial: fechaMin,
      fechaFinal: fechaMax
    }
  }
}];
